#include <vector>
#include <unordered_map>
#include <algorithm>
using namespace std;

class Solution {
public:
    int maxBalancedXorSubarray(vector<int>& nums) {
        unordered_map<int, int> seen;
        seen[0] = -1;
        int cur_xor = 0;
        int max_len = 0;
        for (int i = 0; i < (int)nums.size(); ++i) {
            cur_xor ^= nums[i];
            if (seen.count(cur_xor)) {
                max_len = max(max_len, i - seen[cur_xor]);
            } else {
                seen[cur_xor] = i;
            }
        }
        return max_len;
    }
};

import java.util.*;

class Solution {
    public int maxBalancedXorSubarray(int[] nums) {
        Map<Integer, Integer> seen = new HashMap<>();
        seen.put(0, -1);
        int curXor = 0;
        int maxLen = 0;
        for (int i = 0; i < nums.length; i++) {
            curXor ^= nums[i];
            if (seen.containsKey(curXor)) {
                maxLen = Math.max(maxLen, i - seen.get(curXor));
            } else {
                seen.put(curXor, i);
            }
        }
        return maxLen;
    }
}

var maxBalancedXorSubarray = function(nums) {
    const seen = new Map();
    seen.set(0, -1);
    let curXor = 0;
    let maxLen = 0;
    for (let i = 0; i < nums.length; i++) {
        curXor ^= nums[i];
        if (seen.has(curXor)) {
            maxLen = Math.max(maxLen, i - seen.get(curXor));
        } else {
            seen.set(curXor, i);
        }
    }
    return maxLen;
};
